import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_positions = inputs["target_positions"].copy()
    position_events = inputs["position_events"].copy()

    # Ensure target_positions has the right columns with correct types
    if target_positions.empty:
        target_positions = pd.DataFrame(
            columns=["account_id", "symbol", "qty", "price", "row_version"]
        )
        target_positions = target_positions.astype({
            "account_id": "int64",
            "symbol": "object",
            "qty": "int64",
            "price": "float64",
            "row_version": "int64"
        })

    # Ensure position_events has the right columns with correct types
    if position_events.empty:
        position_events = pd.DataFrame(
            columns=["batch_seq", "account_id", "symbol", "op", "qty", "price", "row_version"]
        )
        position_events = position_events.astype({
            "batch_seq": "int64",
            "account_id": "int64",
            "symbol": "object",
            "op": "object",
            "qty": "float64",
            "price": "float64",
            "row_version": "int64"
        })

    # Step 1: Deduplicate events by batch_seq (keep first occurrence)
    events_dedup = position_events.drop_duplicates(subset=["batch_seq"], keep="first").copy()

    # Step 2: Build a dict of current positions keyed by (account_id, symbol)
    current_state = {}
    for _, row in target_positions.iterrows():
        key = (row["account_id"], row["symbol"])
        current_state[key] = {
            "qty": row["qty"],
            "price": row["price"],
            "row_version": row["row_version"]
        }

    # Step 3: Track which positions were closed by which event (for closed_positions output)
    closed_positions_dict = {}

    # Step 4: Process events in order by row_version, then batch_seq
    events_dedup = events_dedup.sort_values(by=["row_version", "batch_seq"]).reset_index(drop=True)

    for _, event in events_dedup.iterrows():
        key = (int(event["account_id"]), event["symbol"])
        event_row_version = int(event["row_version"])
        op = event["op"]

        # Replay guard: skip if key exists and event row_version <= current row_version
        if key in current_state:
            if event_row_version <= current_state[key]["row_version"]:
                continue

        # Apply the event
        if op == "D":
            # Delete: remove the row if it exists
            if key in current_state:
                closed_positions_dict[key] = event_row_version
                del current_state[key]
        elif op in ("I", "U"):
            # Insert or Update
            event_qty = event["qty"]

            # Handle qty = 0 as a close operation
            if pd.isna(event_qty) or event_qty == 0:
                # Close the position (same as delete)
                if key in current_state:
                    closed_positions_dict[key] = event_row_version
                    del current_state[key]
            else:
                # Regular insert/update
                event_qty = int(event_qty)
                event_price = event["price"]

                if key in current_state:
                    # Update existing row
                    current_state[key]["qty"] = event_qty
                    # For 'U', keep existing price if event price is NULL; for 'I', use event price
                    if op == "U" and pd.isna(event_price):
                        # Keep existing price
                        pass
                    else:
                        current_state[key]["price"] = event_price if not pd.isna(event_price) else None
                    current_state[key]["row_version"] = event_row_version
                else:
                    # Create new row
                    current_state[key] = {
                        "qty": event_qty,
                        "price": event_price if not pd.isna(event_price) else None,
                        "row_version": event_row_version
                    }

    # Step 5: Build output DataFrames
    new_positions_rows = []
    for (account_id, symbol), state in current_state.items():
        new_positions_rows.append({
            "account_id": account_id,
            "symbol": symbol,
            "qty": state["qty"],
            "price": state["price"],
            "row_version": state["row_version"]
        })

    if new_positions_rows:
        new_positions = pd.DataFrame(new_positions_rows)
        new_positions = new_positions.astype({
            "account_id": "int64",
            "symbol": "object",
            "qty": "int64",
            "price": "float64",
            "row_version": "int64"
        })
    else:
        new_positions = pd.DataFrame(
            columns=["account_id", "symbol", "qty", "price", "row_version"]
        ).astype({
            "account_id": "int64",
            "symbol": "object",
            "qty": "int64",
            "price": "float64",
            "row_version": "int64"
        })

    closed_positions_rows = []
    for (account_id, symbol), closed_version in closed_positions_dict.items():
        closed_positions_rows.append({
            "account_id": account_id,
            "symbol": symbol,
            "closed_version": closed_version
        })

    if closed_positions_rows:
        closed_positions = pd.DataFrame(closed_positions_rows)
        closed_positions = closed_positions.astype({
            "account_id": "int64",
            "symbol": "object",
            "closed_version": "int64"
        })
    else:
        closed_positions = pd.DataFrame(
            columns=["account_id", "symbol", "closed_version"]
        ).astype({
            "account_id": "int64",
            "symbol": "object",
            "closed_version": "int64"
        })

    return {
        "new_positions": new_positions,
        "closed_positions": closed_positions
    }
